"""Evolution Theater page served by the local dashboard."""

THEATER_PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AI Bowler · Evolution Theater</title>
<style>
:root{color-scheme:dark;--bg:#080d18;--panel:#101827;--panel2:#121f31;--line:#29394e;--ink:#edf4ff;--muted:#93a7bd;--teal:#49debe;--pink:#fb7185;--violet:#a78bfa;--amber:#fbbf24}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 14% -20%,#183049 0,transparent 36%),var(--bg);color:var(--ink);font:14px/1.5 Inter,Segoe UI,Arial,sans-serif;font-variant-numeric:tabular-nums}a{color:var(--teal)}button,select,input{font:inherit;color:var(--ink)}button,select,input[type=number]{background:#0b1422;border:1px solid #34465f;border-radius:8px;padding:8px 10px}button{cursor:pointer;background:#123043;border-color:#1e6876}button:hover{background:#174253}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--teal);outline-offset:2px}input[type=range]{accent-color:var(--teal)}
.wrap{max-width:1680px;margin:auto;padding:24px 26px 48px}.mast{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:18px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:var(--teal);font-weight:700}.title{font-size:32px;line-height:1.1;margin:5px 0}.sub,.muted{color:var(--muted)}.sub{max-width:76ch}.nav{display:flex;gap:16px;white-space:nowrap;font-size:12px}.toolbar{display:grid;grid-template-columns:auto minmax(180px,1fr) auto auto auto auto;align-items:center;gap:12px;padding:14px 16px;border:1px solid var(--line);background:linear-gradient(145deg,#111c2b,#0c1421);border-radius:14px;margin:20px 0 24px}.toolbar label{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.genrange{min-width:0}.genrange input{width:100%}.genread{color:var(--ink);font-weight:700;min-width:115px;text-align:right}.pill{border:1px solid #2d4e60;border-radius:999px;padding:6px 10px;background:#10202b;color:#b9eee2;font-size:11px;white-space:nowrap}
.section{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin:28px 2px 10px}.section h2{font-size:17px;margin:0}.section span{font-size:11px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.panel{min-width:0;background:linear-gradient(150deg,rgba(18,29,45,.97),rgba(12,20,33,.98));border:1px solid var(--line);border-radius:15px;padding:16px;box-shadow:0 12px 30px #0003}.panel h3{font-size:13px;margin:0 0 4px}.caption{font-size:11px;color:var(--muted);margin:8px 0 0;max-width:90ch}.chart{display:block;width:100%;height:460px;background:#0a111e;border-radius:10px}.short{height:310px}.learning{height:300px}.wide{grid-column:1/-1}.split{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(260px,.55fr);gap:14px}.camSplit{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(260px,.65fr);gap:12px}.ballList{display:flex;flex-direction:column;gap:5px;max-height:380px;overflow:auto}.ball{display:flex;justify-content:space-between;gap:8px;text-align:left;background:#0c1522;border:1px solid #26364a;border-radius:8px;padding:7px 9px;font-size:11px}.ball.active{border-color:var(--teal);box-shadow:0 0 0 1px #49debe33}.ball small{color:var(--muted)}.legend{display:flex;flex-wrap:wrap;gap:10px;font-size:10px;color:var(--muted);margin-top:7px}.legend i{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:5px}.statline{display:flex;flex-wrap:wrap;gap:8px;margin-top:9px}.stat{border:1px solid #27384d;border-radius:8px;padding:6px 9px;color:var(--muted);font-size:11px}.stat b{color:var(--ink);margin-left:5px}.error{color:#ff9baa}.foot{margin-top:24px;text-align:center;color:#72859b;font-size:11px}
@media(max-width:1000px){.toolbar{grid-template-columns:repeat(3,minmax(0,1fr))}.genrange{grid-column:span 2}.genread{grid-column:3}.split,.camSplit{grid-template-columns:1fr}.chart{height:390px}}
@media(max-width:680px){.wrap{padding:17px 12px 32px}.mast{align-items:flex-start;flex-direction:column}.title{font-size:27px}.nav{flex-wrap:wrap}.toolbar{grid-template-columns:1fr 1fr}.genrange{grid-column:1/-1}.genread{grid-column:auto;text-align:left}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.chart{height:320px}.learning{height:260px}}
</style></head><body><main class="wrap">
<header class="mast"><div><div class="eyebrow">AI Bowler · Natural Selection Lab</div><h1 class="title">Evolution Theater</h1><div class="sub">Scrub the population's best policy through training. Network structure, held-out learning, a sampled over and the nearest saved population stay in sync.</div></div><nav class="nav"><a href="/">Live dashboard</a><a href="/brain">Full Brain Explorer</a></nav></header>
<section class="toolbar" aria-label="Evolution controls">
 <label>Run <select id="run"><option value="ga1500">ga1500 · v1</option><option value="ga2">ga2 · v2</option></select></label>
 <label class="genrange">Generation <input id="generation" type="range" min="1" max="1500" value="1" aria-label="Generation from 1 to 1500"></label>
 <div class="genread" id="genRead">gen 1 · loading</div>
 <button id="play">Play</button>
 <label>Speed <select id="speed"><option value="900">1×</option><option value="500">2×</option><option value="220">4×</option></select></label>
 <label>Batter <select id="batter"><option>slogger</option><option>technician</option><option>tailender</option></select></label>
 <label>Seed <input id="seed" type="number" value="10421" min="0" step="1" style="width:100px"></label>
 <button id="saveShot">Save this generation</button>
</section>
<div class="section"><h2 id="networkTitle">Policy network · loading</h2><span>Edges show signed weights; the transition eases between saved genomes.</span></div>
<section class="grid"><article class="panel wide"><h3 id="networkPanelTitle">Network · loading</h3><canvas id="network" class="chart"></canvas><p class="caption">Each input feeds two hidden layers before four release controls. Teal edges add to a signal; pink edges subtract from it. The displayed genome is the nearest saved generation.</p></article></section>
<div class="section"><h2 id="curveTitle">Learning curves · ga1500 + ga2</h2><span>Power cut, gate override and resume are marked on their respective run.</span></div>
<section class="grid"><article class="panel wide"><h3 id="curvePanelTitle">Learning curve · selected run and generation</h3><canvas id="curve" class="chart learning"></canvas><div id="curveLegend" class="legend"></div><p class="caption">Held-out champion validation traces show how robust the policy is on seeds not used for selection. The vertical cursor follows the selected generation; labeled markers identify run events.</p></article></section>
<div class="section"><h2 id="overTitle">Brain Cam · selected generation</h2><span id="overStamp">One seeded over · choose a batter above.</span></div>
<section class="grid"><article class="panel wide"><h3 id="overPanelTitle">Sampled over · selected generation</h3><div class="camSplit"><canvas id="pitch" class="chart short"></canvas><div><div class="statline" id="overStats"></div><div class="ballList" id="balls"></div></div></div><div class="legend"><span><i style="background:#fb7185"></i>wicket</span><span><i style="background:#5ee0a0"></i>runs</span><span><i style="background:#8094aa"></i>dot</span><span><i style="background:#fbbf24"></i>extra</span></div><p class="caption">This is the selected genome's actual simulated over against the chosen batter and seed. Select a ball to highlight its landing point.</p></article></section>
<div class="section"><h2 id="populationTitle">Population cloud · nearest saved generation</h2><span id="populationStamp">Common PCA basis across all saved populations.</span></div>
<section class="grid"><article class="panel wide"><h3 id="populationPanelTitle">Population snapshot · selected generation</h3><canvas id="population" class="chart short"></canvas><p class="caption">Each dot is a genome in the nearest saved population, projected into the same PCA basis. Colour shows fitness; the amber marker highlights the champion and outlined point its ancestry at this snapshot.</p></article></section>
<footer class="foot">Local read-only explorer · one run, batter and seed are shared by the brain and over panels.</footer>
</main><script src="/brain_panels.js"></script><script>
const RUNS=__RUNS__,DEFAULT_RUN=__DEFAULT_RUN__, $=id=>document.getElementById(id);const query=new URLSearchParams(location.search);$('run').value=RUNS.includes(query.get('run'))?query.get('run'):(RUNS.includes(DEFAULT_RUN)?DEFAULT_RUN:'ga2');$('generation').value=Math.max(1,Math.min(1500,Number(query.get('generation'))||1));
const api=async(p,q)=>{const r=await fetch(p+'?'+new URLSearchParams(q),{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);return d};
let selected=null,playTimer=null,requestToken=0,selectedBall=0;
const num=v=>v!==''&&v!=null&&Number.isFinite(+v)?+v:null;
function setContext(data){const ctx=`${data.run} · gen ${String(data.requested_generation).padStart(4,'0')} (saved ${String(data.saved_generation).padStart(4,'0')})`;for(const id of ['networkTitle','networkPanelTitle','curveTitle','curvePanelTitle','overTitle','overPanelTitle','populationTitle','populationPanelTitle'])$(id).textContent=$(id).textContent.split(' · ')[0]+' · '+ctx;document.title=`${data.run} gen ${data.requested_generation} · Evolution Theater`;}
function interpolate(a,b,t){if(!a)return b;return {...b,weights:b.weights.map((m,l)=>m.map((row,i)=>row.map((v,j)=>a.weights[l]?.[i]?.[j]==null?v:a.weights[l][i][j]*(1-t)+v*t))),biases:b.biases.map((v,l)=>v.map((x,i)=>a.biases[l]?.[i]==null?x:a.biases[l][i]*(1-t)+x*t))}}
function morphNetwork(from,to){const start=performance.now(),duration=360;function step(now){const t=Math.min(1,(now-start)/duration),e=t*t*(3-2*t);BrainPanels.drawNetwork($('network'),interpolate(from,to,e),360);if(t<1)requestAnimationFrame(step)}requestAnimationFrame(step)}
function drawCurve(data){const c=$('curve'),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,r=c.getBoundingClientRect();c.width=r.width*dpr;c.height=r.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const w=r.width,h=r.height,p={l:50,r:18,t:18,b:34};ctx.fillStyle='#0a111e';ctx.fillRect(0,0,w,h);ctx.font='10px Segoe UI';ctx.strokeStyle='#29394e';ctx.fillStyle='#93a7bd';const vals=[];for(const run of ['ga1500','ga2'])for(const row of data.runs[run].rows){let v=num(row.champion_validation_score||row.validation_score);if(v!==null)vals.push(v)}const lo=Math.min(0,...vals),hi=Math.max(1.15,...vals),X=g=>p.l+(g-1)/1499*(w-p.l-p.r),Y=v=>h-p.b-(v-lo)/(hi-lo)*(h-p.t-p.b);for(let i=0;i<=4;i++){const y=p.t+i*(h-p.t-p.b)/4;ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(w-p.r,y);ctx.stroke();ctx.fillText((hi-(hi-lo)*i/4).toFixed(2),4,y+3)}for(const [run,color] of [['ga1500','#a78bfa'],['ga2','#49debe']]){let previous=null;ctx.beginPath();for(const row of data.runs[run].rows){const g=num(row.gen),v=num(row.champion_validation_score||row.validation_score);if(g===null||v===null)continue;const point=[X(g),Y(v)];if(previous)ctx.lineTo(point[0],point[1]);else ctx.moveTo(point[0],point[1]);previous=point}ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();for(const row of data.runs[run].rows){const g=num(row.gen),v=num(row.champion_validation_score||row.validation_score);if(g===null||v===null)continue;ctx.beginPath();ctx.arc(X(g),Y(v),2.5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}}const cursor=X(data.requested_generation);ctx.setLineDash([4,4]);ctx.strokeStyle='#edf4ff';ctx.beginPath();ctx.moveTo(cursor,p.t);ctx.lineTo(cursor,h-p.b);ctx.stroke();ctx.setLineDash([]);for(const [run,color] of [['ga1500','#a78bfa'],['ga2','#49debe']])for(const ev of data.runs[run].events||[]){if(!['power_cut','resume','gate_override'].includes(ev.type))continue;const x=X(+ev.generation||+ev.interrupted_after_generation||1);ctx.beginPath();ctx.arc(x,p.t+8,4,0,Math.PI*2);ctx.fillStyle=ev.type==='power_cut'?'#fb7185':ev.type==='gate_override'?'#fbbf24':color;ctx.fill()}$('curveLegend').innerHTML='<span><i style="background:#a78bfa"></i>ga1500 validation</span><span><i style="background:#49debe"></i>ga2 validation</span><span><i style="background:#fb7185"></i>power cut</span><span><i style="background:#fbbf24"></i>gate override</span><span><i style="background:#93a7bd"></i>resume</span>';}
function ballColor(d){return d.delivery.wicket?'#fb7185':d.delivery.result==='runs'?'#5ee0a0':(!d.delivery.legal?'#fbbf24':'#8094aa')}
function renderOver(data){const deliveries=data.cam.deliveries||[];selectedBall=Math.min(selectedBall,Math.max(0,deliveries.length-1));BrainPanels.drawPitch($('pitch'),deliveries.map((d,i)=>({length_m:d.delivery.length_m,line_m:d.delivery.line_m,result:d.delivery.result,current:i===selectedBall?i:undefined})));let wickets=0,runs=0,legal=0;for(const d of deliveries){wickets+=d.delivery.wicket?1:0;runs+=d.delivery.runs;legal+=d.delivery.legal?1:0}$('overStats').innerHTML=`<span class="stat">runs<b>${runs}</b></span><span class="stat">wickets<b>${wickets}</b></span><span class="stat">legal balls<b>${legal}/6</b></span><span class="stat">deliveries<b>${deliveries.length}</b></span>`;$('balls').innerHTML=deliveries.map((d,i)=>`<button class="ball ${i===selectedBall?'active':''}" data-ball="${i}"><span><b>${i+1}.</b> ${d.release.speed_kmh.toFixed(0)} km/h · ${d.delivery.category}</span><small style="color:${ballColor(d)}">${d.delivery.result}${d.delivery.wicket?' · wicket':''}${d.delivery.runs?` · ${d.delivery.runs} runs`:''}</small></button>`).join('');$('balls').querySelectorAll('[data-ball]').forEach(b=>b.addEventListener('click',()=>{selectedBall=+b.dataset.ball;renderOver(data)}));$('overStamp').textContent=`${data.archetype} · seed ${data.seed} · ${deliveries.length} deliveries · ${data.checkpoint}`;}
async function load(){const token=++requestToken;const generation=+$('generation').value,run=$('run').value,archetype=$('batter').value,seed=+$('seed').value||0;$('genRead').textContent=`gen ${generation} · loading`;try{const data=await api('/api/theater',{run,generation,archetype,seed});if(token!==requestToken)return;const old=selected?.network||null;selected=data;setContext(data);$('genRead').textContent=`gen ${generation} · saved ${data.saved_generation}`;morphNetwork(old,data.network);drawCurve(data);renderOver(data);const pop=data.population||{};if(pop.points)BrainPanels.drawPopulation($('population'),{...pop,ancestry_ids:data.ancestry_ids||[]});else{$('population').getContext('2d').clearRect(0,0,$('population').width,$('population').height)}$('populationStamp').textContent=pop.error||`snapshot ${pop.snapshot_generation} · ${pop.points?.length||0} genomes · ${(100*((pop.explained_variance||[0,0]).slice(0,2).reduce((a,b)=>a+b,0))).toFixed(1)}% variance on PC1–2`; }catch(e){$('genRead').textContent=e.message;$('genRead').classList.add('error')}}
let debounce; $('generation').addEventListener('input',()=>{clearTimeout(debounce);$('genRead').textContent=`gen ${$('generation').value}`;debounce=setTimeout(load,100)});$('run').addEventListener('change',load);$('batter').addEventListener('change',()=>{selectedBall=0;load()});$('seed').addEventListener('change',()=>{selectedBall=0;load()});$('play').addEventListener('click',()=>{if(playTimer){clearInterval(playTimer);playTimer=null;$('play').textContent='Play';return}$('play').textContent='Pause';playTimer=setInterval(()=>{let g=+$('generation').value;if(g>=1500){clearInterval(playTimer);playTimer=null;$('play').textContent='Play';return}$('generation').value=g+1;load()},+$('speed').value)});window.addEventListener('keydown',e=>{if(e.target.matches('input,select,button'))return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();$('generation').value=Math.max(1,Math.min(1500,+$('generation').value+(e.key==='ArrowRight'?1:-1)));load()}});window.addEventListener('resize',()=>{if(selected){BrainPanels.drawNetwork($('network'),selected.network,360);drawCurve(selected);renderOver(selected);if(selected.population?.points)BrainPanels.drawPopulation($('population'),{...selected.population,ancestry_ids:selected.ancestry_ids||[]})}});load();
</script><script>
function saveTheaterSnapshot(){if(!selected)return;const c=document.createElement('canvas'),w=1600,h=1120;c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#080d18';x.fillRect(0,0,w,h);x.fillStyle='#edf4ff';x.font='600 28px Segoe UI';x.fillText(`Evolution Theater · ${selected.run} · generation ${selected.requested_generation} (saved ${selected.saved_generation})`,32,42);const cells=[['Policy network',$('network')],['Held-out learning curve',$('curve')],['Sampled Brain Cam over',$('pitch')],['Nearest population snapshot',$('population')]],gap=24,cw=(w-3*gap)/2,ch=(h-3*gap-70)/2;cells.forEach((item,i)=>{const col=i%2,row=Math.floor(i/2),cx=gap+col*(cw+gap),cy=62+gap+row*(ch+gap);x.fillStyle='#101827';x.strokeStyle='#29394e';x.beginPath();x.roundRect(cx,cy,cw,ch,12);x.fill();x.stroke();x.fillStyle='#93a7bd';x.font='600 14px Segoe UI';x.fillText(`${item[0]} · ${selected.run} · gen ${selected.requested_generation}`,cx+14,cy+23);const source=item[1],scale=Math.min((cw-24)/source.width,(ch-48)/source.height);x.drawImage(source,cx+12+(cw-24-source.width*scale)/2,cy+34+(ch-48-source.height*scale)/2,source.width*scale,source.height*scale)});const a=document.createElement('a');a.download=`Theater_${selected.run}_gen_${String(selected.requested_generation).padStart(4,'0')}.png`;a.href=c.toDataURL('image/png');a.click()}
$('saveShot').addEventListener('click',saveTheaterSnapshot);
</script></body></html>'''
